const sectionTop=(num,label,title,desc='',action='')=>`<div class="section-top reveal"><div>${eyebrow(`${num} / ${label}`)}<h2>${title}</h2></div><div class="section-aside">${desc?`<p>${desc}</p>`:''}${action}</div></div>`;
function card(m,i=0){return `<article class="machine-card"><a class="machine-image" href="/equipment/${m.id}/"><span class="machine-number mono">${String(i+1).padStart(2,'0')}</span><span class="machine-category">${m.group==='attachment'?'Машина + оборудование':groups[m.group]}</span><img src="${A+m.image}" alt="${m.name} — фото категории из материалов СТТ-Сервис" loading="lazy" width="600" height="420"></a><div class="machine-info"><h3><a href="/equipment/${m.id}/">${m.name}</a></h3><p>${m.desc}</p><div class="spec-mini"><div><b>${m.weight}</b><small>${m.group==='utility'?'Базовая машина':'Масса'}</small></div><div><b>${m.width}</b><small>${m.id==='auger'?'Диаметр шнека':m.id==='hammer'?'Энергия удара':m.group==='utility'?'Захват':'Ширина'}</small></div><div><b>${m.depth}</b><small>${m.id==='wheeled'?'Оборудование':m.group==='loader'?'Грузоподъёмность':m.group==='utility'?'Назначение':m.id==='hammer'?'Высота работы':'Глубина'}</small></div></div><div class="machine-price"><div><strong>${money(m.price)}</strong><small>${m.price?'ориентир за смену · 8 часов':'рассчитаем под ваш объект'}</small></div><a class="square-link" href="/equipment/${m.id}/" aria-label="Подробнее: ${m.name}">${arrow}</a></div><div class="machine-tools"><button class="compare-button ${compared.includes(m.id)?'selected':''}" data-compare="${m.id}">${compareIcon}${compared.includes(m.id)?'В сравнении':'Сравнить'}</button></div></div></article>`}
function faq(){return `<section class="section"><div class="wrap faq-grid"><div class="reveal">${eyebrow('07 / Разберёмся в деталях')}<h2>Перед<br>началом работ.</h2><p class="muted">То, что чаще всего спрашивают перед заказом техники.</p></div><div class="faq-list reveal">${FAQ.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`}
