function workContent(){return `<div class="work-grid"><figure class="work-main reveal" style="margin:0"><img src="${A}36c.jpg" alt="Мини-экскаватор выполняет земляные работы" loading="lazy" width="1024" height="682"><figcaption class="work-caption"><div><h3>Точность там, где мало места.</h3><p>Мини-экскаватор · Земляные работы</p></div><span class="mono">01 ↗</span></figcaption></figure><figure class="work-secondary reveal" style="margin:0"><img src="${A}34c.webp" alt="Мини-погрузчик перемещает грунт" loading="lazy" width="1000" height="667"><figcaption class="work-caption"><div><h3>Переместить. Распределить.<br>Подготовить.</h3><p>Мини-погрузчик · Работа с материалами</p></div><span class="mono">02 ↗</span></figcaption></figure></div><p class="work-source">Фотографии из публичных материалов <a href="https://stt-servis.ru/" target="_blank" rel="noopener">СТТ-Сервис</a> показывают применение техники. Состав машины и оборудования для вашего заказа согласуем отдельно.</p>`}
function serviceGrid(){return `<div class="service-grid">${Object.entries(services).map(([id,s],i)=>`<a class="service-item" href="/services/${id}/"><span class="mono">0${i+1}</span><h3>${s.name}</h3><p>${id==='transport'?'Грузы и спецтехника. Подбор транспорта и маршрута.':id==='landscape'?'Подготовка участков и механизированные работы.':id==='repair'?'Обслуживание строительной техники и грузовиков.':'Фильтры, детали двигателей и трансмиссии.'}</p>${arrow}</a>`).join('')}</div>`}
function home(){return `<section class="hero wrap"><div class="hero-meta">${eyebrow('Спецтехника с оператором')}<span>СТТ-Сервис / Москва и область</span></div><div class="hero-grid"><div class="hero-copy"><h1>Малый<br><span class="inset">габарит.</span><br>Большая<br><span class="accent inset">работа.</span></h1><p class="hero-intro">Мини-экскаваторы и погрузчики для вашего объекта. Подберём технику, оборудование и организуем подачу.</p><div class="hero-actions">${button('Подобрать технику','data-picker')}<a class="textlink" href="/catalog/">Весь каталог ${arrow}</a></div></div><div class="hero-photo"><img src="${A}104.jpg" alt="Компактный экскаватор Kubota на земляных работах" fetchpriority="high" width="1500" height="1000"><span class="photo-cross">+</span><div class="photo-label"><div>Компактная техника.<br>Серьёзные задачи.</div><span>55°45′ N<br>37°37′ E</span></div></div><div class="round-tag">Подберём<strong>ПОД ВАС</strong>и ваш объект</div></div><div class="hero-bottom"><div><span class="mono">01</span><span>Москва<br>и Московская область</span></div><div><span class="mono">02</span><span>Техника<br>с оператором</span></div><div><span class="mono">03</span><span>Подбор навесного<br>оборудования</span></div><div><span class="mono">04</span><span>Договор<br>и удобная оплата</span></div></div></section>
<section class="section" id="tasks"><div class="wrap">${sectionTop('01','Начнём с задачи','Что нужно<br>сделать?', 'Название машины знать необязательно. Достаточно рассказать, какой результат вам нужен.')}<div class="task-list reveal">${tasks.map((t,i)=>`<a class="task-row" href="/tasks/${t.id}/"><span class="mono">0${i+1}</span><h3>${t.name}</h3><small>${t.short}</small>${arrow}</a>`).join('')}</div><div class="task-note"><span>Есть особенности участка или нестандартная задача?</span><button class="textlink" data-picker style="border-top:0;border-left:0;border-right:0;background:none">Обсудить с нами ${arrow}</button></div></div></section>
<section class="section fleet" id="fleet"><div class="wrap">${sectionTop('02','Каталог техники','Компактные.<br>Но способные.', 'Выбирайте по задаче, габаритам и условиям объекта.', '<a class="textlink" href="/catalog/">Вся техника '+arrow+'</a>')}<div class="tabs" role="tablist" aria-label="Категории техники"><button class="tab active" role="tab" aria-selected="true" data-fleet="mini">Мини-экскаваторы</button><button class="tab" role="tab" aria-selected="false" data-fleet="loader">Мини-погрузчики</button><button class="tab" role="tab" aria-selected="false" data-fleet="attachment">С оборудованием</button></div><div class="machine-grid" id="home-fleet" role="tabpanel">${machines.filter(m=>m.group==='mini').map(card).join('')}</div><div class="catalog-note"><span>Стоимость — ориентир из каталога компании. Доставку и комплектацию уточним под объект.</span><a href="/conditions/">Условия аренды ↗</a></div></div></section>
<section class="section selection"><div class="wrap selection-grid"><div class="reveal">${eyebrow('03 / Правильный выбор')}<h2>Каждый объект —<br><span class="accent">свои условия.</span></h2><p>Узкие ворота, сложный грунт или работа рядом с постройками. Учтём детали до того, как машина отправится к вам.</p>${button('Разобраться с подбором','data-picker')}</div><div class="selection-steps reveal"><div class="selection-step"><span class="mono">01</span><div><h3>Расскажите о работе</h3><p>Задача, объём, желаемый результат.</p></div>${arrow}</div><div class="selection-step"><span class="mono">02</span><div><h3>Покажите условия объекта</h3><p>Адрес, проезд, особенности территории.</p></div>${arrow}</div><div class="selection-step"><span class="mono">03</span><div><h3>Согласуем подходящий вариант</h3><p>Машина, оборудование, дата и стоимость.</p></div>${arrow}</div></div></div><div class="selection-watermark" aria-hidden="true">СТТ</div></section>
<section class="section"><div class="wrap">${sectionTop('04','Техника в деле','Работу<br>видно.', 'Как компактные машины справляются с земляными работами и перемещением материалов.', '<a class="textlink" href="/work/">Смотреть фотографии '+arrow+'</a>')}${workContent()}</div></section>
<section class="section services"><div class="wrap">${sectionTop('05','Больше возможностей','Рядом с вашей<br>основной задачей.', 'Перевозки, подготовка территории, обслуживание и подбор деталей.')}${serviceGrid()}</div></section>
<section class="section company"><div class="wrap company-grid"><div class="reveal">${eyebrow('06 / О компании')}<h2>Небольшая<br>команда.<br>Личное<br>отношение.</h2></div><div class="company-text reveal"><p>За каждой машиной — люди, которые знают свою работу. Обсуждаем задачу напрямую и подбираем технику с учётом вашего объекта.</p><div class="company-details"><div><small>Наша география</small><p>Москва и Московская область</p></div><div><small>Наш подход</small><p>От задачи — к подходящей машине</p></div></div><a class="textlink" href="/company/">Познакомиться с компанией ${arrow}</a></div></div></section>
${faq()}${contactBanner()}`}
function intro(title,desc='',label='',crumbTitle=''){return `<section class="page-intro wrap"><div class="crumb"><a href="/">Главная</a><span>/</span><span>${crumbTitle||title.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ')}</span></div>${label?eyebrow(label):''}<h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</section>`}
function catalog(){let q=new URLSearchParams(location.search);currentGroup=q.get('group')&&groups[q.get('group')]?q.get('group'):'all';currentAttachment='';maxWidth='';sort='recommended';return `${intro('Техника.<br><span class="accent">Под вашу задачу.</span>','Выбирайте по габаритам, рабочим параметрам и оборудованию. Или расскажите об объекте — поможем с подбором.','Каталог спецтехники','Каталог')}<div class="wrap catalog-layout"><aside class="filters" aria-label="Фильтры каталога"><h3>Подбор по параметрам</h3><button class="filter-toggle" data-toggle-filters aria-expanded="false">Настроить фильтры ${compareIcon}</button><div class="filter-groups"><div class="filter-group"><span>Категория</span>${Object.entries(groups).map(([id,t])=>`<label><input type="radio" name="group" value="${id}" ${currentGroup===id?'checked':''}>${t}</label>`).join('')}</div><div class="filter-group"><span>Проезд на объект</span><label><input type="checkbox" name="narrow">До 1,6 м по ширине</label></div><div class="filter-group"><span>Оборудование</span><label><input type="radio" name="attachment" value="" checked>Любое</label>${['auger','hammer','forks','brush'].map(a=>`<label><input type="radio" name="attachment" value="${a}">${attachments[a]}</label>`).join('')}</div></div><button class="filter-reset" data-reset-filters>Сбросить фильтры</button><button class="btn filter-done" data-toggle-filters>Показать варианты ${arrow}</button></aside><div><div class="catalog-toolbar"><span id="catalog-count"></span><select id="sort" aria-label="Сортировка"><option value="recommended">Рекомендуемые</option><option value="price">По стоимости</option><option value="weight">По массе</option><option value="width">По ширине</option></select></div><div class="active-filters" id="active-filters"></div><div class="machine-grid" id="catalog-results"></div><div class="catalog-note"><span>Фотографии показывают категорию техники. Конкретную модель, доступность и окончательную стоимость согласуем при заказе.</span></div></div></div>${contactBanner()}`}
function filteredMachines(){let list=machines.filter(m=>(currentGroup==='all'||m.group===currentGroup)&&(!currentAttachment||m.tags.includes(currentAttachment))&&(!maxWidth||(parseFloat(m.width.replace(',','.'))<=1.6&&m.group==='mini')));if(sort==='price')list.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==='weight')list.sort((a,b)=>(parseFloat(a.weight.replace(',','.'))||Infinity)-(parseFloat(b.weight.replace(',','.'))||Infinity));if(sort==='width')list.sort((a,b)=>(parseFloat(a.width.replace(',','.'))||Infinity)-(parseFloat(b.width.replace(',','.'))||Infinity));return list;}
function updateCatalog(){const list=filteredMachines();$('#catalog-count').textContent=`Вариантов техники: ${list.length}`;$('#catalog-results').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>Проверим другие решения.</h3><p>По этим параметрам вариантов нет. Измените фильтры или расскажите о задаче — поможем с подбором.</p>${button('Подобрать с нами','data-picker')}</div>`;$('#active-filters').innerHTML=[currentGroup!=='all'?groups[currentGroup]:'',currentAttachment?attachments[currentAttachment]:'',maxWidth?'Проезд до 1,6 м':''].filter(Boolean).map(t=>`<span class="chip">${t}</span>`).join('');}
function equipment(m){return `${intro(m.name,m.desc,'Машина и условия аренды',m.name)}<div class="wrap equipment-top"><div><div class="gallery-main"><span class="gallery-index mono">01 / ФОТО КАТЕГОРИИ</span><img id="gallery-image" src="${A+m.image}" alt="${m.name} — изображение категории" width="1000" height="700"></div><div class="gallery-thumbs">${[m.image,m.second].filter((v,i,a)=>a.indexOf(v)===i).map((img,i)=>`<button class="${i===0?'active':''}" data-gallery="${img}" aria-label="Фотография ${i+1}"><img src="${A+img}" alt=""></button>`).join('')}</div><p class="gallery-caption">Фотографии из материалов компании. Конкретная машина и комплектация согласуются при заказе.</p></div><div class="equipment-summary">${eyebrow('Подбор и организация подачи')}<h2>Готова к вашей<br><span class="accent">задаче.</span></h2><p>${m.desc} Уточним доступность на нужную дату и условия работы.</p><div class="price-big"><strong>${money(m.price)}</strong><small>${m.price?'за 8-часовую смену':''}</small><p>${m.price?`${money(m.hour)} / час — справочный тариф. Минимальный заказ и доставка согласуются отдельно.`:'Стоимость зависит от модели, оборудования и расположения объекта.'}</p></div><div class="rent-notes"><span>Техника с оператором</span><span>Доставка на объект</span><span>Работа по договору</span><span>Уточнение комплектации</span></div>${button('Уточнить стоимость и дату',`data-picker data-equipment="${m.id}"`)}<a class="textlink" href="${CONTACT.tg}" target="_blank" rel="noopener">Обсудить в Telegram ${arrow}</a></div></div><div class="wrap equipment-details"><div>${eyebrow('01 / Технические данные')}<h2>Параметры,<br>которые важны.</h2><table class="spec-table"><tbody>${m.specs.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table><p class="gallery-caption">Параметры категории по опубликованному каталогу. Точные характеристики выделенной машины подтвердим перед заказом.</p></div><div>${eyebrow('02 / Применение')}<h2>Для вашей<br>работы.</h2><div class="application-list">${m.uses.map(id=>{const t=tasks.find(t=>t.id===id);return `<a href="/tasks/${id}/">${t.title}${arrow}</a>`}).join('')}</div><h3 style="margin-top:32px;font-size:17px">Необходимое оборудование</h3><div class="attachment-list">${m.tags.map(a=>`<button class="attachment" data-attachment-select="${a}" aria-pressed="false">${attachments[a]}</button>`).join('')}</div><p class="gallery-caption">Выбранное оборудование добавится в ваш запрос. Совместимость и стоимость уточним при согласовании.</p><div class="access-panel"><h3>Пройдёт ли машина?</h3><p>Измерьте ширину ворот и самого узкого участка проезда. Сообщите об уклонах, слабом грунте и ограничениях по высоте.</p><a class="textlink" href="/journal/access/">Как подготовить подъезд ${arrow}</a></div></div></div><section class="section fleet"><div class="wrap">${sectionTop('03','Другие варианты','Есть с чем<br>сравнить.')}<div class="machine-grid">${machines.filter(x=>x.id!==m.id&&x.group===m.group).slice(0,3).map(card).join('')||machines.slice(0,3).map(card).join('')}</div></div></section>${faq()}${contactBanner()}`}
function taskPage(t){let options=machines.filter(m=>m.uses.includes(t.id)).slice(0,3);return `${intro(t.title,t.desc,'От задачи к технике',t.title)}<div class="wrap split-page"><img src="${A+t.photo}" alt="Техника для задачи: ${t.title}" width="1000" height="700"><div class="split-copy">${eyebrow('Учитываем условия объекта')}<h2>Сначала — детали.<br>Потом — машина.</h2><p>Чтобы предложить подходящую технику, уточним объём, доступ к месту работ и ограничения на объекте.</p><ul class="bullet-list">${t.needs.map(n=>`<li>${n}</li>`).join('')}</ul>${button('Подготовить запрос',`data-picker data-task="${t.id}"`)}</div></div><section class="section fleet"><div class="wrap">${sectionTop('01','Подходящие варианты','Техника для<br>этой работы.')}<div class="machine-grid">${options.map(card).join('')}</div></div></section>${faq()}${contactBanner()}`}
function servicePage(id){const s=services[id];return `${intro(s.title.replace(/\n/g,'<br>'),s.desc,'Услуги СТТ-Сервис',s.name)}<div class="wrap split-page"><img src="${A+s.photo}" alt="${s.name} — иллюстрация направления из материалов компании" width="1500" height="1000"><div class="split-copy">${eyebrow('Под вашу ситуацию')}<h2>${s.name}</h2><ul class="bullet-list">${s.items.map(x=>`<li>${x}</li>`).join('')}</ul><p>Возможность выполнения, стоимость и сроки уточняются по вашему запросу.</p>${button(id==='transport'?'Рассчитать перевозку':'Обсудить задачу',`data-picker data-service="${id}"`)}</div></div><section class="section services"><div class="wrap">${sectionTop('01','Для точного ответа','Какие данные<br>нам помогут.')}<div class="info-columns">${s.needs.map((n,i)=>`<div class="info-column"><span class="mono muted">0${i+1}</span><h3>${n}</h3><p>${i===0?'Начните с основной информации. Если чего-то не знаете, уточним вместе.':i===1?'Размеры, фото и описание помогут точнее понять задачу.':'Сообщите известные детали при обращении.'}</p></div>`).join('')}</div></div></section>${contactBanner()}`}
function companyPage(){return `${intro('Люди.<br>Техника.<br><span class="accent">Общее дело.</span>','СТТ-Сервис — аренда спецтехники и транспортные услуги в Москве и Московской области.','О компании','Компания')}<div class="wrap split-page"><img src="${A}104.jpg" alt="Мини-экскаватор из материалов СТТ-Сервис" width="1500" height="1000"><div class="split-copy">${eyebrow('Личное отношение к работе')}<h2>Небольшая команда.<br>Прямой контакт.</h2><p>Наша команда — давно знакомые люди, объединённые общим делом. Обсуждаем задачу и условия объекта, чтобы подобрать подходящее решение.</p><p>В предложении — мини-экскаваторы, мини-погрузчики, перевозки, обслуживание техники и запчасти.</p><a class="textlink" href="/contact/">Связаться с нами ${arrow}</a></div></div><section class="section company"><div class="wrap company-grid"><div>${eyebrow('Как устроена работа')}<h2>Один объект.<br>Много деталей.<br>Всё обсудим.</h2></div><div class="company-text"><p>Подходящая машина начинается с правильных вопросов. Где работать, как проехать, что выполнить и какое оборудование потребуется.</p><div class="company-details"><div><small>География</small><p>Москва и Московская область</p></div><div><small>Организация заказа</small><p>Подбор, согласование, подача</p></div></div></div></div></section><section class="section"><div class="wrap">${sectionTop('01','Направления компании','Работаем<br>с вашей задачей.')}${serviceGrid()}</div></section>${contactBanner()}`}
function workPage(){return `${intro('Техника.<br><span class="accent">В своей стихии.</span>','Фотографии применения компактной техники из открытых материалов компании.','Рабочие процессы','Техника в работе')}<section class="section" style="padding-top:15px"><div class="wrap">${workContent()}<div class="work-grid" style="margin-top:50px"><figure class="work-main" style="margin:0"><img src="${A}49c.jpg" alt="Гусеничный мини-погрузчик" loading="lazy"><figcaption class="work-caption"><div><h3>Уверенная опора.</h3><p>Гусеничная ходовая · Работа с материалами</p></div><span class="mono">03</span></figcaption></figure><figure class="work-secondary" style="margin:0"><img src="${A}54c.jpg" alt="Перевозка строительной техники" loading="lazy"><figcaption class="work-caption"><div><h3>Работа начинается с доставки.</h3><p>Перевозка техники</p></div><span class="mono">04</span></figcaption></figure></div></div></section>${contactBanner()}`}
function conditionsPage(){return `${intro('Всё важное.<br><span class="accent">До начала работ.</span>','Согласуем условия вашего заказа заранее. Здесь — основные вопросы, которые стоит обсудить.','Условия аренды','Условия аренды')}<div class="wrap article"><h2>Продолжительность заказа</h2><p>В опубликованных условиях компании указан минимальный заказ от 8 часов. В карточках приведён ориентир за смену. Начало отсчёта времени, дополнительные часы и специальные условия согласуются при заказе.</p><h2>Что входит в стоимость</h2><p>Уточните состав услуги: оператор, ГСМ, выбранное навесное оборудование и необходимые дополнительные работы. Итог зависит от комплектации и задачи.</p><h2>Доставка на объект</h2><p>Для расчёта подачи сообщите адрес, особенности подъезда и место выгрузки. Время доставки зависит от маршрута и доступности техники. Подтверждённая дата и стоимость фиксируются при согласовании.</p><h2>Оплата и документы</h2><p>Компания заявляет наличную и безналичную оплату, работу по договору. НДС, ЭДО и перечень документов уточняются для конкретного заказа.</p><h2>Подготовка участка</h2><p>Проверьте ширину и высоту проезда, возможность выгрузки, состояние грунта. Заранее сообщите о коммуникациях, уклонах, слабых покрытиях и других ограничениях.</p><h2>Цены в каталоге</h2><p>На этом сайте приведены справочные тарифы из опубликованного каталога СТТ-Сервис. Это ориентир для выбора. Актуальность цены, доставка и окончательный состав заказа подтверждаются при обращении.</p>${button('Уточнить условия','data-picker')}</div>${contactBanner()}`}
function contactForm(){return `<form id="contact-form"><label class="form-field"><span>Что нужно сделать?</span><textarea name="comment" required placeholder="Например: выкопать траншею на участке, проезд 1,8 м"></textarea></label><label class="form-field"><span>Где находится объект?</span><input name="location" placeholder="Населённый пункт или адрес" autocomplete="street-address"></label><div class="field-row"><label class="form-field"><span>Как к вам обращаться?</span><input name="name" autocomplete="name" placeholder="Имя"></label><label class="form-field"><span>Как с вами связаться?</span><input name="contact" required placeholder="Телефон или @username" autocomplete="tel"></label></div>${button('Подготовить запрос','type="submit"')}<p class="form-hint">Вы сможете проверить текст и самостоятельно отправить его в Telegram или по почте. <a href="/privacy/">О ваших данных</a>.</p></form>`}
function contactPage(){return `${intro('Начнём<br><span class="accent">с разговора.</span>','Расскажите, что нужно сделать. Уточним детали и предложим подходящий вариант.','Контакты','Контакты')}<div class="wrap contact-grid"><div><div class="contact-block"><small>Основной телефон</small><a class="large" href="${CONTACT.tel}">${CONTACT.phone}</a></div><div class="contact-block"><small>Сообщения и почта</small><div class="contact-actions">${link('Telegram',CONTACT.tg,'outline')}<a class="textlink" href="mailto:${CONTACT.email}">${CONTACT.email}${arrow}</a></div></div><div class="contact-block"><small>Офис</small><p>Мытищи, ул. Колонцова,<br>д. 5, оф. 204</p><p style="font-size:12px;margin-top:15px;color:var(--muted)">График в опубликованных контактах: ежедневно, 09:00–21:00. Перед визитом уточните время.</p><div class="contact-map"><div class="map-lines" aria-hidden="true"></div><div class="map-pin">${arrow}</div><p>Московская область<br>Мытищи, ул. Колонцова, 5</p><a class="textlink" href="https://yandex.ru/maps/?text=${encodeURIComponent(CONTACT.address)}" target="_blank" rel="noopener">Открыть в Яндекс Картах ${arrow}</a></div></div><div class="contact-block"><small>Дополнительные телефоны</small><a href="tel:+74957416877">+7 (495) 741-68-77</a><br><a href="tel:+79997191893">+7 (999) 719-18-93</a></div></div><div class="contact-form-box"><h2>Ваш объект.<br>Ваша задача.</h2><p>Добавьте известные детали — это поможет быстрее обсудить заказ.</p>${contactForm()}</div></div>`}
const articles={access:{title:'Как подготовить подъезд',desc:'Несколько измерений помогают избежать сложностей при подаче техники.',parts:[['Измерьте самое узкое место','Ширина ворот — только один параметр. Проверьте весь маршрут машины до места работ: повороты, проходы между постройками, деревья и выступающие детали.'],['Уточните ограничения по высоте','Обратите внимание на навесы, ветки и другие препятствия. Сообщите высоту самого низкого участка.'],['Проверьте поверхность','Мягкий грунт, слабая плитка, люки, уклоны и края откосов влияют на маршрут и выбор техники. Опишите их при заказе.'],['Сделайте фотографии','Общий вид подъезда, узкое место и территория работ помогут обсудить решение. Фото можно приложить непосредственно в переписке с компанией.'],['Согласуйте место выгрузки','Транспорту нужна возможность безопасно подъехать и разгрузиться. Уточните доступ, ограничения и необходимость пропуска.']]},shift:{title:'Что обсудить перед заказом смены',desc:'Продолжительность — только часть условий. Важно заранее согласовать состав работы.',parts:[['Продолжительность и время учёта','Уточните минимальную смену, момент начала отсчёта, время подачи и стоимость дополнительных часов.'],['Оператор и топливо','Согласуйте, входят ли оператор и ГСМ в стоимость и какие условия относятся к вашему заказу.'],['Оборудование','Перечислите необходимые ковши и навесное оборудование. Обсудите возможность их использования на выбранной машине.'],['Доставка','Сообщите точное расположение объекта и условия выгрузки. Уточните стоимость подачи и обратной перевозки.'],['Документы и оплата','Согласуйте договор, способ оплаты и необходимые документы до начала работы.']]},choice:{title:'Как выбрать мини-экскаватор',desc:'Ориентируйтесь на задачу и условия объекта, затем сравнивайте машины.',parts:[['Начните с результата','Опишите, что нужно сделать: траншея, выемка грунта, бурение или демонтаж. Сообщите предполагаемый объём.'],['Проверьте рабочие параметры','Для земляных работ важны глубина копания, ширина ковша и высота погрузки. Для оборудования — совместимость и необходимые параметры работы.'],['Учтите габариты','Машина должна пройти до места работ и иметь пространство для безопасного движения и поворота.'],['Обсудите грунт и ограничения','Сообщите о слабом грунте, уклонах, коммуникациях и близких строениях.'],['Попросите помочь с подбором','Если параметры неизвестны, фотографии и описание объекта помогут специалисту задать нужные вопросы.']]}};
function journalPage(id){if(id&&articles[id]){const a=articles[id];return `${intro(a.title,a.desc,'Подготовка к работе',a.title)}<div class="wrap article">${a.parts.map(([t,p])=>`<h2>${t}</h2><p>${p}</p>`).join('')}${button('Помочь с подбором','data-picker')}</div>${contactBanner()}`;}return `${intro('Детали,<br>которые помогают.','Короткие материалы о выборе машины и подготовке объекта.','Полезные материалы','Полезные материалы')}<section class="section" style="padding-top:20px"><div class="wrap info-columns">${Object.entries(articles).map(([id,a],i)=>`<a class="info-column" href="/journal/${id}/"><span class="mono muted">0${i+1}</span><h3>${a.title}</h3><p>${a.desc}</p><span class="textlink" style="margin-top:25px">Читать ${arrow}</span></a>`).join('')}</div></section>${contactBanner()}`}
function privacyPage(){return `${intro('Данные<br>и конфиденциальность.','','О сайте','Конфиденциальность')}<div class="wrap article"><h2>Подготовка запроса</h2><p>Формы этого сайта собирают текст запроса в вашем браузере. Запрос не отправляется в СТТ-Сервис автоматически. После подготовки вы можете скопировать его, открыть Telegram или почтовую программу и отправить самостоятельно.</p><h2>Контактные данные</h2><p>Имя, контакт, адрес и описание задачи используются для составления запроса. Они не сохраняются сайтом в базу обращений. Перед отправкой в выбранном сервисе проверьте текст.</p><h2>Сравнение техники</h2><p>Выбор машин для сравнения сохраняется локально в вашем браузере. Для очистки воспользуйтесь кнопкой закрытия панели сравнения или очистите данные сайта.</p><h2>Внешние сервисы</h2><p>Ссылки на Telegram, почту, карты и исходный сайт открывают соответствующие сервисы. Их обработка данных регулируется правилами этих сервисов.</p><h2>Вопросы</h2><p>Для обращения к компании используйте телефон ${CONTACT.phone} или почту ${CONTACT.email}.</p></div>`}
function render(){const pathname=BASE&&location.pathname.startsWith(BASE+'/')?location.pathname.slice(BASE.length):location.pathname===BASE?'/':location.pathname;const path=pathname.replace(/\/+$/,'')||'/';const parts=path.split('/').filter(Boolean);let content,title='СТТ-Сервис — техника под задачу';if(path==='/')content=home();else if(path==='/catalog'){content=catalog();title='Каталог спецтехники — СТТ-Сервис';}else if(parts[0]==='equipment'&&machines.some(m=>m.id===parts[1])){const m=machines.find(m=>m.id===parts[1]);content=equipment(m);title=m.name+' — СТТ-Сервис';}else if(parts[0]==='tasks'&&tasks.some(t=>t.id===parts[1])){const t=tasks.find(t=>t.id===parts[1]);content=taskPage(t);title=t.title+' — СТТ-Сервис';}else if(parts[0]==='services'&&services[parts[1]]){content=servicePage(parts[1]);title=services[parts[1]].name+' — СТТ-Сервис';}else if(path==='/company'){content=companyPage();title='О компании — СТТ-Сервис';}else if(path==='/work'){content=workPage();title='Техника в работе — СТТ-Сервис';}else if(path==='/conditions'){content=conditionsPage();title='Условия аренды — СТТ-Сервис';}else if(path==='/contact'){content=contactPage();title='Контакты — СТТ-Сервис';}else if(parts[0]==='journal'){content=journalPage(parts[1]);title='Полезные материалы — СТТ-Сервис';}else if(path==='/privacy')content=privacyPage();else content=`<div class="wrap not-found"><h1>404</h1><h2>Здесь страницы нет.<br>Техника — в каталоге.</h2>${link('Перейти в каталог','/catalog/')}</div>`;$('#main').innerHTML=content;const mobileAction=$('#mobilebar [data-picker]');if(parts[0]==='equipment'&&machines.some(m=>m.id===parts[1])){mobileAction.dataset.equipment=parts[1];mobileAction.innerHTML='Уточнить'+arrow;}else{delete mobileAction.dataset.equipment;mobileAction.innerHTML='Подобрать'+arrow;}document.title=title;$$('[data-nav]').forEach(a=>a.classList.toggle('active',parts[0]===a.dataset.nav));$('.mobile-menu').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Открыть меню');if(path==='/catalog')updateCatalog();observeReveal();renderCompareBar();if(location.hash){setTimeout(()=>$(location.hash)?.scrollIntoView({behavior:'smooth'}),80);}}
function observeReveal(){const elements=$$('.reveal');if(matchMedia('(prefers-reduced-motion: reduce)').matches){elements.forEach(el=>el.classList.add('visible'));return;}const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}}),{threshold:.08});elements.forEach(el=>obs.observe(el));}
function navigate(url){history.pushState({},'',url);render();if(!location.hash)window.scrollTo({top:0,behavior:'instant'});$('#main').setAttribute('tabindex','-1');$('#main').focus({preventScroll:true});}
function toast(t){$('.toast').textContent=t;$('.toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('.toast').classList.remove('show'),2800);}
function saveCompared(){try{localStorage.setItem('stt-comparison',JSON.stringify(compared))}catch{}}
function renderCompareBar(){$('.compare-bar')?.remove();if(compared.length){document.body.insertAdjacentHTML('beforeend',`<div class="compare-bar"><span>В сравнении: ${compared.length} / 3</span>${button('Сравнить','data-open-compare') }<button data-clear-compare aria-label="Очистить сравнение">×</button></div>`)}$$('[data-compare]').forEach(b=>{const selected=compared.includes(b.dataset.compare);b.classList.toggle('selected',selected);b.innerHTML=compareIcon+(selected?'В сравнении':'Сравнить')});}
function openCompare(){const list=compared.map(id=>machines.find(m=>m.id===id));$('#compare').className='compare-dialog';$('#compare').innerHTML=`<div class="dialog-head">${eyebrow('Выбор по параметрам')}<button class="icon-button" data-close aria-label="Закрыть сравнение">${closeIcon}</button></div><div class="dialog-body"><h2 id="compare-title">Сравним варианты.</h2><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>Техника</th>${list.map(m=>`<th><img src="${A+m.image}" alt=""><a href="/equipment/${m.id}/">${m.name}</a></th>`).join('')}</tr></thead><tbody>${[['Масса','weight'],['Ширина / оборудование','width'],['Рабочий параметр','depth'],['Ориентир за смену','price']].map(([label,key])=>`<tr><td>${label}</td>${list.map(m=>`<td>${key==='price'?money(m[key]):m[key]}</td>`).join('')}</tr>`).join('')}<tr><td>Оборудование</td>${list.map(m=>`<td>${m.tags.map(t=>attachments[t]).join(', ')}</td>`).join('')}</tr><tr><td>Уточнить заказ</td>${list.map(m=>`<td><button class="textlink" data-picker data-equipment="${m.id}" style="border:0;background:none;padding:0">Подобрать ${arrow}</button></td>`).join('')}</tr></tbody></table></div></div>`;$('#compare').showModal();}
function openPicker(el){const selected=$$('.attachment.selected').map(a=>a.dataset.attachmentSelect);pickerState={...pickerState,step:el.dataset.task||el.dataset.equipment||el.dataset.service?1:0,task:el.dataset.task||el.dataset.service||'',equipment:el.dataset.equipment||'',attachment:selected};$('#compare').close();renderPicker();$('#picker').showModal();}
function requestText(){const m=machines.find(m=>m.id===pickerState.equipment);const task=tasks.find(t=>t.id===pickerState.task);const service=services[pickerState.task];let rows=['Здравствуйте! Хочу обсудить заказ в СТТ-Сервис.'];if(task||service)rows.push('Задача: '+(task?.title||service?.name));if(m)rows.push('Техника: '+m.name);if(pickerState.attachment.length)rows.push('Оборудование: '+pickerState.attachment.map(a=>attachments[a]).join(', '));if(pickerState.location)rows.push('Объект: '+pickerState.location);if(pickerState.date){const [y,mo,d]=pickerState.date.split('-');rows.push('Желаемая дата: '+[d,mo,y].join('.'));}if(pickerState.access)rows.push('Условия подъезда: '+pickerState.access);if(pickerState.comment)rows.push('Детали: '+pickerState.comment);if(pickerState.name)rows.push('Имя: '+pickerState.name);if(pickerState.contact)rows.push('Контакт: '+pickerState.contact);rows.push('Пожалуйста, уточните подходящий вариант, доступность, состав услуги и итоговую стоимость.');return rows.join('\n');}
function dateMin(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function renderPicker(){const s=pickerState;const titles=['Что нужно сделать?','Условия вашего объекта.','Как с вами связаться?','Запрос готов.'];let body='';if(s.step===0){body=`<p>Начните с задачи. Если пока сложно описать — разберёмся вместе.</p><div class="picker-choices">${[...tasks,{id:'other',name:'Нужна помощь с выбором'}].map(t=>`<button type="button" class="picker-choice ${s.task===t.id?'selected':''}" data-pick-task="${t.id}">${t.name}${arrow}</button>`).join('')}</div>`;}else if(s.step===1){body=`<p>${s.equipment?'Выбрана техника: '+machines.find(m=>m.id===s.equipment)?.name:s.task&&services[s.task]?'Направление: '+services[s.task].name:'Сообщите известные детали. Неизвестные параметры можно уточнить в разговоре.'}</p><form id="picker-form"><label class="form-field"><span>${s.task==='transport'?'Маршрут: откуда и куда':'Где расположен объект?'} *</span><input name="location" value="${esc(s.location)}" required placeholder="Населённый пункт или адрес" autocomplete="street-address"></label><div class="field-row"><label class="form-field"><span>Желаемая дата</span><input type="date" name="date" value="${esc(s.date)}" min="${dateMin()}"></label><label class="form-field"><span>Проезд и ограничения</span><input name="access" value="${esc(s.access)}" placeholder="Ширина, грунт, пропуск"></label></div><label class="form-field"><span>Детали задачи</span><textarea name="comment" placeholder="Размеры, объём, оборудование или описание неисправности">${esc(s.comment)}</textarea></label><div class="picker-nav"><button type="button" class="picker-back" data-picker-back>← Назад</button>${button('Продолжить','type="submit"')}</div></form>`;}else if(s.step===2){body=`<p>Добавьте удобный контакт. Перед отправкой вы сможете проверить весь текст.</p><form id="picker-form"><label class="form-field"><span>Как к вам обращаться?</span><input name="name" value="${esc(s.name)}" autocomplete="name" placeholder="Ваше имя"></label><label class="form-field"><span>Телефон или Telegram *</span><input name="contact" value="${esc(s.contact)}" required minlength="3" autocomplete="tel" placeholder="+7 … или @username"></label><p class="form-hint">Запрос подготовится в браузере. Отправка — по вашему действию в выбранном сервисе. <a href="/privacy/">О данных</a>.</p><div class="picker-nav"><button type="button" class="picker-back" data-picker-back>← Назад</button>${button('Проверить запрос','type="submit"')}</div></form>`;}else{body=`<p>Проверьте текст, скопируйте его и отправьте компании в Telegram. Фотографии объекта можно добавить в переписке.</p><div class="request-preview" tabindex="0">${esc(requestText())}</div><div class="request-actions">${button('Скопировать запрос','data-copy-request')}<a class="btn dark" href="${CONTACT.tg}" target="_blank" rel="noopener">Открыть Telegram ${telegramIcon}</a><a class="btn outline" href="mailto:${CONTACT.email}?subject=${encodeURIComponent('Запрос на технику — СТТ-Сервис')}&body=${encodeURIComponent(requestText())}">Отправить по почте ${arrow}</a></div><div class="picker-nav"><button class="picker-back" data-picker-back>← Изменить данные</button><button class="picker-back" data-close>Закрыть</button></div>`;}
 $('#picker').innerHTML=`<div class="dialog-head">${eyebrow(`Подбор техники / ${String(s.step+1).padStart(2,'0')} из 04`)}<button class="icon-button" data-close aria-label="Закрыть подбор">${closeIcon}</button></div><div class="dialog-body"><div class="picker-progress" aria-label="Шаг ${s.step+1} из 4">${[0,1,2,3].map(i=>`<span class="${i<=s.step?'active':''}"></span>`).join('')}</div><h2 id="picker-title">${titles[s.step]}</h2>${body}</div>`;$('#picker').scrollTop=0;if($('#picker').open){const heading=$('#picker-title');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}}
async function copyRequest(){try{await navigator.clipboard.writeText(requestText());toast('Запрос скопирован. Отправьте его в Telegram.')}catch{const node=$('.request-preview');const range=document.createRange();range.selectNodeContents(node);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);toast('Текст выделен. Скопируйте его вручную.')}}
document.addEventListener('click',e=>{const el=e.target.closest('a,button');if(!el)return;if(el.matches('.menu-toggle')){const open=$('.mobile-menu').classList.toggle('open');el.setAttribute('aria-expanded',open);el.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');return;}if(el.matches('[data-picker]')){openPicker(el);return;}if(el.matches('[data-close]')){el.closest('dialog').close();return;}if(el.matches('[data-fleet]')){$$('[data-fleet]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-selected',b===el?'true':'false')});$('#home-fleet').innerHTML=machines.filter(m=>m.group===el.dataset.fleet).slice(0,3).map(card).join('');return;}if(el.matches('[data-compare]')){const id=el.dataset.compare;if(compared.includes(id))compared=compared.filter(x=>x!==id);else if(compared.length<3)compared.push(id);else{toast('Можно сравнить до трёх машин.');return;}saveCompared();renderCompareBar();return;}if(el.matches('[data-open-compare]')){openCompare();return;}if(el.matches('[data-clear-compare]')){compared=[];saveCompared();renderCompareBar();return;}if(el.matches('[data-toggle-filters]')){const panel=$('.filters');const open=panel.classList.toggle('open');const toggle=$('.filter-toggle');toggle.setAttribute('aria-expanded',String(open));toggle.innerHTML=(open?'Скрыть фильтры':'Настроить фильтры')+compareIcon;if(!open&&el.classList.contains('filter-done'))$('.catalog-toolbar').scrollIntoView({behavior:'smooth',block:'start'});return;}if(el.matches('[data-reset-filters]')){currentGroup='all';currentAttachment='';maxWidth='';$$('[name=group]').forEach(x=>x.checked=x.value==='all');$$('[name=attachment]').forEach(x=>x.checked=x.value==='');$('[name=narrow]').checked=false;updateCatalog();return;}if(el.matches('[data-gallery]')){$('#gallery-image').src=A+el.dataset.gallery;$$('[data-gallery]').forEach(b=>b.classList.toggle('active',b===el));return;}if(el.matches('[data-attachment-select]')){const yes=el.classList.toggle('selected');el.setAttribute('aria-pressed',yes);return;}if(el.matches('[data-pick-task]')){pickerState.task=el.dataset.pickTask;pickerState.step=1;renderPicker();return;}if(el.matches('[data-picker-back]')){if($('#picker-form')){const data=new FormData($('#picker-form'));data.forEach((v,k)=>pickerState[k]=String(v));}pickerState.step=Math.max(0,pickerState.step-1);renderPicker();return;}if(el.matches('[data-copy-request]')){copyRequest();return;}if(el.tagName==='A'&&el.getAttribute('href')?.startsWith('/')&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();el.closest('dialog')?.close();navigate(el.getAttribute('href'));}});
document.addEventListener('change',e=>{if(e.target.matches('[name=group]')){currentGroup=e.target.value;updateCatalog();}if(e.target.matches('[name=attachment]')){currentAttachment=e.target.value;updateCatalog();}if(e.target.matches('[name=narrow]')){maxWidth=e.target.checked?'1.6':'';updateCatalog();}if(e.target.matches('#sort')){sort=e.target.value;updateCatalog();}});
document.addEventListener('submit',e=>{if(e.target.id==='picker-form'){e.preventDefault();const data=new FormData(e.target);data.forEach((v,k)=>pickerState[k]=String(v).trim());pickerState.step++;renderPicker();}if(e.target.id==='contact-form'){e.preventDefault();pickerState={step:3,task:'other',equipment:'',attachment:[],location:'',date:'',access:'',comment:'',name:'',contact:''};new FormData(e.target).forEach((v,k)=>pickerState[k]=String(v).trim());renderPicker();$('#picker').showModal();}});
for(const d of $$('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.mobile-menu').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}});
window.addEventListener('popstate',()=>{render();window.scrollTo(0,0)});
shell();render();normalizeLinks();
